/// Create all events for DAO space initialization (returns Vec in correct order)
pub fn dao_space_initialized(
    space_id: SpaceId,
    initial_editors: &[Address],
    initial_members: &[Address],
) -> Vec<Action> {
    let mut events = Vec::new();

    // 1. SPACE_ID_REGISTERED
    events.push(Action {
        from_id: vec![0u8; 16],
        to_id: space_id.to_vec(),
        action: actions::SPACE_REGISTERED.to_vec(),
        topic: vec![0u8; 32],  // No owner for DAO
        data: vec![],
    });

    // 2. SPACE_TYPE_DECLARED
    events.push(space_type_declared(space_id, SPACE_TYPE_DAO, b"1.0.0"));

    // 3. EDITOR_ADDED for each initial editor
    for editor in initial_editors {
        events.push(editor_added(space_id, *editor));
    }

    // 4. MEMBER_ADDED for each initial member
    for member in initial_members {
        events.push(member_added(space_id, *member));
    }

    events
}

