```rust
pub fn transform(actions: &[Action], meta: &BlockMetadata) -> Result<TransformResult> {
    let mut events = Vec::new();
    let mut i = 0;

    while i < actions.len() {
        let action = &actions[i];

        if !actions::matches(&action.action, &actions::SPACE_REGISTERED) {
            i += 1;
            continue;
        }

        // Extract space_id from to_id (new contract format)
        let space_id = action.to_id.clone();
        let owner = action.topic.clone();

        // Look ahead for paired SPACE_TYPE_DECLARED
        let space_type = if i + 1 < actions.len() {
            let next = &actions[i + 1];
            if actions::matches(&next.action, &actions::SPACE_TYPE_DECLARED) 
               && next.from_id == space_id 
            {
                i += 1;  // Consume the paired event
                Some(next.topic.clone())
            } else {
                None
            }
        } else {
            None
        };

        // Determine payload based on space_type
        let payload = match space_type.as_deref() {
            Some(t) if t == actions::SPACE_TYPE_DAO => {
                // Empty payload - editors/members come via membership events
                Some(hermes_create_space::Payload::DefaultDaoSpace(
                    DefaultDaoSpacePayload {}
                ))
