### src/pipelines/proposals.rs (update or create)

**Squash PROPOSAL_CREATED + PROPOSAL_SETTINGS_USED:**
```rust
pub fn transform(actions: &[Action], meta: &BlockMetadata) -> Result<TransformResult> {
    let mut events = Vec::new();
    let mut i = 0;

    while i < actions.len() {
        let action = &actions[i];

        if !actions::matches(&action.action, &actions::PROPOSAL_CREATED) {
            i += 1;
            continue;
        }

        let space_id = action.from_id.clone();  // from_id == to_id for DAOSpace actions
        let proposal_id = action.topic[0..16].to_vec();  // bytes16 padded to bytes32
        let (prop_id, voting_mode, prop_actions) = decode_proposal_data(&action.data)?;

        // Look ahead for paired PROPOSAL_SETTINGS_USED
        let settings = if i + 1 < actions.len() {
            let next = &actions[i + 1];
            if actions::matches(&next.action, &actions::PROPOSAL_SETTINGS_USED)
               && next.topic == action.topic  // Same proposal_id
            {
                i += 1;  // Consume the paired event
                Some(decode_proposal_settings(&next.data)?)
            } else {
                None
            }
        } else {
            None
        };

        events.push(HermesProposalCreated {
            space_id,
            proposal_id,
            voting_mode,
            actions: prop_actions,
            settings,
            meta: Some(meta.to_proto(i as u32)),
        });

        i += 1;
    }

    Ok(TransformResult { events })
}
```

